import {entryCalculations,damageExpression,diceTerms} from './calculations.mjs';
import {sheetSkills} from './skills.mjs';
import {abilities,number,signed,sheetStats,skillTotal,weaponAttack} from './model.mjs';
import {characterClasses,totalClassLevel} from '../characters/ffd20.mjs';
export const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escape;
export const sections=[['favorites','Favorites'],['overview','Character'],['combat','Combat'],['skills','Skills'],['items','Inventory'],['abilities','Abilities'],['spells','Spells'],['notes','Notes']];
export const abilityTabs=['activeAbilities','passiveAbilities','racialAbilities','feats'];
const svg=paths=>'<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths+'</svg>';
export const icons={
 favorites:svg('<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z"/>'),
 overview:svg('<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>'),
 combat:svg('<path d="M14.5 17.5 3 6V3h3l11.5 11.5M13 19l6-6m-3 3 4 4m-1 1 2-2"/>'),
 skills:svg('<rect x="3" y="3" width="18" height="18" rx="4"/><circle cx="8" cy="8" r=".8"/><circle cx="16" cy="8" r=".8"/><circle cx="12" cy="12" r=".8"/><circle cx="8" cy="16" r=".8"/><circle cx="16" cy="16" r=".8"/>'),
 items:svg('<path d="M8 5V3h8v2M5 10a7 7 0 0 1 14 0v10H5Z"/><rect x="8" y="13" width="8" height="5" rx="1"/><path d="M3 11v7m18-7v7M9 9h6"/>'),
 notes:svg('<rect x="5" y="3" width="15" height="18" rx="2"/><path d="M3 7h4M3 12h4M3 17h4M10 8h6m-6 4h6m-6 4h4"/>'),
 recovery:svg('<path d="M3 11a9 9 0 1 1 3 8M3 5v6h6"/><path d="M12 8v8m-4-4h8"/>'),
 discord:svg('<path d="M8 5 5 6c-2 3-3 7-3 11l5 2 1-2m8-12 3 1c2 3 3 7 3 11l-5 2-1-2M7 7c3-1 7-1 10 0M6 16c4 2 8 2 12 0"/><ellipse cx="8.5" cy="12" rx="1" ry="1.5"/><ellipse cx="15.5" cy="12" rx="1" ry="1.5"/>')
};
const fightSections=['combat','abilities','spells'];
export const titles={items:'Items',weapons:'Weapons',spells:'Spells',activeAbilities:'Active',passiveAbilities:'Passive',racialAbilities:'Racial',feats:'Feats',skills:'Skills'};
const edit=(group,label='Edit')=>`<button class="cs-icon" type="button" data-edit-stats="${group}" aria-label="Edit ${e(label)}" title="Edit ${e(label)}">✎</button>`;
const card=(title,content,action='')=>`<section class="cs-card${title==='Base'?' cs-base':''}"><div class="cs-card-title"><h2>${title}</h2>${action}</div>${content}</section>`;
const metric=(label,value,{roll=false}={})=>`<div class="cs-metric-wrap"><${roll?'button type="button" data-roll="'+e(label)+'" data-bonus="'+number(value)+'"':'div'} class="cs-metric"><span>${label}</span><strong>${roll?signed(value):e(value)}</strong></${roll?'button':'div'}><button class="cs-formula-button" type="button" data-formula="${e(label)}" aria-label="Show ${e(label)} calculation">ⓘ</button></div>`;
export function renderSheetFrame(character,section='overview',{admin=false,compact=false,ability='activeAbilities',combatView='defense'}={}){
 const d=character.data||{},classes=characterClasses(d).filter(c=>c.name),total=totalClassLevel(classes)||number(d.character_level||d.level),portrait=typeof d.portrait==='string'&&/^data:image\/(jpeg|png|webp);base64,[\w+/=]+$/i.test(d.portrait)&&d.portrait.length<=160000?d.portrait:'';
 return `<div class="cs-sheet" data-sheet><div class="cs-titlebar"><div class="cs-identity">${portrait?'<img class="cs-portrait" src="'+e(portrait)+'" alt="">':''}<div><span class="cs-kicker">${e(d.race||'Character')} · Total level ${total||'—'}</span><h1>${e(character.name)}</h1><p class="cs-classline">${classes.map((c,i)=>'<span title="Class '+(i+1)+' Lv">'+e(c.name)+' '+e(c.level)+(c.archetype?' · '+e(c.archetype):'')+'</span>').join(' / ')}</p></div></div><a class="cs-icon" href="create-identity.html?characterId=${encodeURIComponent(character.id)}" aria-label="Edit character build" title="Edit character build">✎</a></div>
 <div class="cs-syncbar"><span class="cs-sync-dot" aria-hidden="true"></span><span role="status" data-sheet-status>Synced${admin?' · Admin':''}</span><button type="button" class="cs-text-button" data-sheet-refresh hidden>Load latest</button>${!compact?'<a class="cs-icon" aria-label="Open compact sheet in a new window" title="Open compact sheet" href="sheet.html?characterId='+encodeURIComponent(character.id)+'&compact=1" target="_blank" rel="noopener">↗</a>':''}</div>
 <nav class="cs-tabs" aria-label="Character sheet">${[['favorites','Favorites'],['overview','Character'],['combat','Combat'],['skills','Skills'],['items','Inventory'],['notes','Notes']].map(([key,title])=>`<button type="button" data-sheet-tab="${key}" aria-pressed="${key==='combat'?fightSections.includes(section):section===key}" aria-label="${key==='combat'?'Combat, abilities and spells':title}" title="${title}">${icons[key]}</button>`).join('')}</nav>
 ${fightSections.includes(section)?'<nav class="cs-tabs cs-subtabs" aria-label="Combat sections">'+fightSections.map(key=>'<button type="button" data-sheet-tab="'+key+'" aria-pressed="'+(section===key)+'">'+({combat:'Combat',abilities:'Abilities',spells:'Spells'}[key])+'</button>').join('')+'</nav>':''}
 ${section==='abilities'?'<label class="cs-category-select"><span class="sr-only">Ability category</span><select data-ability-category aria-label="Ability category">'+abilityTabs.map(key=>'<option value="'+key+'"'+(ability===key?' selected':'')+'>'+titles[key]+' · '+(Array.isArray(d[key])?d[key].length:0)+'</option>').join('')+'</select></label>':''}
 <div class="cs-roll-tools"><label class="cs-discord-icon" title="Send rolls to Discord"><input type="checkbox" class="sr-only" data-discord-rolls aria-label="Send rolls to Discord" checked><span>${icons.discord}</span></label><details class="cs-recovery cs-recovery-menu"><summary aria-label="Recovery" title="Recovery">${icons.recovery}</summary><div><button class="button" type="button" data-rest>Rest</button>${edit('resources','resource maximums')}</div></details></div><div data-sheet-panel>${renderSection(character,section,{ability,combatView})}</div><div class="cs-roll-result" role="status" data-roll-result hidden></div>
 <dialog class="cs-dialog" data-sheet-dialog aria-labelledby="cs-dialog-title"><form data-sheet-form><div class="cs-card-title"><h2 id="cs-dialog-title"></h2><button type="button" class="cs-icon" data-dialog-close aria-label="Close">×</button></div><div data-dialog-fields></div><p role="status" data-dialog-status></p><div class="cs-dialog-actions"><button class="button" type="button" data-dialog-close>Cancel</button><button class="button primary" type="submit">Save</button></div></form></dialog></div>`;
}
export function renderSection(character,section,{ability='activeAbilities',combatView='defense'}={}){
 const d=character.data||{},s=sheetStats(d);
 if(section==='overview'){
  const scoreCards=abilities.map(a=>`<button class="cs-score" type="button" data-roll="${a.toUpperCase()} check" data-bonus="${s.mods[a]}"><span>${a.toUpperCase()}</span><strong>${d[a]===undefined||d[a]===''?'—':e(d[a])}</strong><small>${signed(s.mods[a])}</small></button>`).join('');
  return `<div class="cs-grid">${card('Ability scores','<div class="cs-scores">'+scoreCards+'</div>',edit('abilities','ability scores'))}${card('Identity','<dl class="cs-pairs">'+[['Alignment',d.alignment],['Size',d.size_category||d.size||'Medium'],['Languages',d.languages],['Senses',d.senses]].map(([k,v])=>'<div><dt>'+k+'</dt><dd>'+e(v||'—')+'</dd></div>').join('')+'</dl>',edit('identity','identity details'))}${card('Bio','<p class="cs-prose">'+e(d.bio||'No bio yet.')+'</p>','<a class="cs-text-button" href="create-identity.html?characterId='+encodeURIComponent(character.id)+'">Edit</a>')}</div>`;
 }
 if(section==='favorites'){
  const groups=['weapons','activeAbilities','passiveAbilities','racialAbilities','feats'].map(key=>{const entries=(Array.isArray(d[key])?d[key]:[]).map((row,index)=>({row,index})).filter(({row})=>row.favorite===true);return entries.length?'<section class="cs-collection"><h2>'+titles[key]+'</h2><div class="cs-entry-list">'+entries.map(({row,index})=>entry(key,row,index,d)).join('')+'</div></section>':'';}).join('');
  return '<h2>Favorites</h2>'+(groups||'<p class="cs-caption">Star a weapon or ability to keep it here.</p>');
 }
 if(section==='combat')return `<div class="cs-resources">${resource('HP',s.hp,s.hpMax,'hp_curr',s.hpTemp)}${resource('MP',s.mp,s.mpMax,'mp_curr')}</div>
 ${card('Base','<div class="cs-metrics">'+metric('Initiative',s.initiative,{roll:true})+metric('BAB',signed(s.bab))+metric('Speed',s.speed)+'</div>',edit('base','base combat values'))}
 <section class="cs-card cs-battle-block"><nav class="cs-tabs cs-subtabs" aria-label="Offense and defense">${['offense','defense'].map(key=>'<button type="button" data-combat-view="'+key+'" aria-pressed="'+(combatView===key)+'">'+(key==='offense'?'Offense':'Defense')+'</button>').join('')}</nav>
 ${combatView==='offense'?'<div class="cs-section-tools"><h2>Actions</h2>'+edit('attack','attack bonuses')+'</div><div class="cs-metrics">'+metric('Melee',s.melee,{roll:true})+metric('Ranged',s.ranged,{roll:true})+metric('Touch attack',s.touchAttack,{roll:true})+metric('Ranged touch',s.rangedTouch,{roll:true})+metric('CMB',s.cmb,{roll:true})+'</div>'+collectionBlock('weapons',d):'<div class="cs-defense-hero"><button type="button" class="cs-defense-shield" data-formula="AC" aria-label="Show Armor class calculation"><span>Armor class</span><strong>'+s.ac+'</strong></button>'+edit('defense','defense')+'</div><div class="cs-metrics">'+metric('Touch',s.touch)+metric('Flat-footed',s.flat)+metric('CMD',s.cmd)+'</div>'}
 </section><div class="cs-grid cs-battle-bottom">${card('Saving throws','<div class="cs-metrics">'+metric('Fortitude',s.fort,{roll:true})+metric('Reflex',s.ref,{roll:true})+metric('Will',s.will,{roll:true})+'</div>',edit('saves','saving throws'))}${card('Resistances','<p class="cs-prose">'+e(d.resistances||'—')+'</p>',edit('resistances','resistances'))}</div>`;
 if(section==='skills')return `<div class="cs-section-tools"><h2>Skills</h2></div><p class="cs-caption">Ability + ranks + misc + 3 for a trained class skill</p>${search()}<div data-sheet-list>${renderSkillRows(d)}</div>`;
 if(section==='items')return `<div class="cs-section-tools"><h2>Inventory</h2>${edit('currency','currency & capacity')}</div><div class="cs-currency"><span>Gil <strong>${e(d.currency_gil??d.gil??0)}</strong></span><span>Moogle <strong>${e(d.currency_moogle??0)}</strong></span><span>Capacity <strong>${e(d.slot_cap??20)}</strong></span></div>${search()}<div data-sheet-list>${collectionBlock('items',d)}</div>`;
 if(section==='abilities')return `${search()}<div data-sheet-list>${collectionBlock(abilityTabs.includes(ability)?ability:'activeAbilities',d)}</div>${ability==='feats'?card('Proficiencies','<p class="cs-prose">'+e(d.proficiencies||'—')+'</p>',edit('proficiencies','proficiencies')):''}`;
 if(section==='spells')return `<div class="cs-spellbar"><span>MP <strong>${s.mp} / ${s.mpMax}</strong></span><span>Base <strong>${e(String(d.spell_dc_base||'int').toUpperCase())}</strong></span><button class="button" type="button" data-spend-mp>Spend MP</button>${edit('spell','spell settings')}</div>${search()}<div data-sheet-list>${collectionBlock('spells',d)}</div>`;
 return card('Notes',`<form data-notes><label class="sr-only" for="cs-notes">Character notes</label><textarea id="cs-notes" name="notesArea" rows="8" maxlength="12000" placeholder="A few things to remember…">${e(d.notesArea||'')}</textarea><button class="button primary" type="submit">Save notes</button></form>`);
}
function resource(label,current,max,key,temp){return `<section class="cs-resource"><div><h2>${label}</h2><span>/ ${max}</span></div><div class="cs-resource-controls"><button type="button" data-resource="${key}" data-delta="-1" aria-label="Decrease ${label}">−</button><input type="number" data-resource-input="${key}" value="${current}" aria-label="Current ${label}" step="any"><button type="button" data-resource="${key}" data-delta="1" aria-label="Increase ${label}">+</button></div>${key==='hp_curr'?'<label class="cs-temp-hp"><span>Temp HP</span><input type="number" min="0" step="1" data-resource-input="hp_temp" value="'+number(temp)+'" aria-label="Temporary HP"></label>':''}</section>`;}
const search=()=>'<label class="cs-search"><span class="sr-only">Find an entry</span><input type="search" data-sheet-search placeholder="Find an entry…"></label>';
export function collectionBlock(key,d,query=''){
 const rows=Array.isArray(d[key])?d[key]:[],matches=rows.map((row,index)=>({row,index})).filter(({row})=>String(row.name||'').toLowerCase().includes(query.toLowerCase()));
 return `<section class="cs-collection"><div class="cs-section-tools"><h2>${titles[key]} <span class="cs-count">${rows.length}</span></h2><button type="button" class="cs-icon" data-add-entry="${key}" aria-label="Add ${e(titles[key])}" title="Add">+</button></div><div class="cs-entry-list">${matches.map(({row,index})=>entry(key,row,index,d)).join('')||'<p class="cs-caption">'+(query?'No matches.':'No entries yet.')+'</p>'}</div></section>`;
}
function entry(key,row,index,d){
 const ability=key==='activeAbilities',spell=key==='spells',weapon=key==='weapons';let calculated;try{calculated=entryCalculations(row,d,key);}catch{}
 const meta=[spell?'Lv '+e(row.lvl||0):'',row.type,row.range,weapon?(row.damage||row.dmg):'',key==='items'?'× '+(row.amount??1):''].filter(Boolean).map(e).join(' · ');
 return `<article class="cs-entry"><div class="cs-entry-heading"><details data-entry-details="${key}:${index}"><summary><strong>${e(row.name||'Unnamed')}</strong>${meta?'<small>'+meta+'</small>':''}</summary><div data-entry-detail-body></div></details><div class="cs-entry-actions">${['weapons','activeAbilities','passiveAbilities','racialAbilities','feats'].includes(key)?'<button type="button" class="cs-favorite" data-favorite="'+key+':'+index+'" aria-label="Favorite '+e(row.name||titles[key])+'" aria-pressed="'+(row.favorite===true)+'">'+icons.favorites+'</button>':''}${key==='items'?`<label class="cs-equip"><input type="checkbox" data-equipment="${index}" ${row.equipped?'checked':''}><span>Equip</span></label>`:''}${ability&&calculated?.maxUses>0?'<button class="cs-use" type="button" data-use="'+index+'" aria-label="Use '+e(row.name)+'">'+calculated.currentUses+' / '+calculated.maxUses+'</button>':''}${weapon?'<button class="cs-weapon-attack" type="button" data-roll="'+e(row.name)+' attack" data-bonus="'+weaponAttack(row,d)+'" aria-label="Roll '+e(row.name)+' attack">Attack '+signed(weaponAttack(row,d))+'</button>'+(/^[0-9]+d[0-9]+(?:[+-][0-9]+)?$/i.test(String(row.damage||row.dmg||'').replaceAll(' ',''))?'<button class="cs-weapon-attack" type="button" data-damage-roll="'+e(row.damage||row.dmg)+'" data-damage-label="'+e(row.name)+'">Damage</button>':''):''}<button class="cs-icon" type="button" data-edit-entry="${key}:${index}" aria-label="Edit ${e(row.name||titles[key])}" title="Edit">✎</button></div></div></article>`;
}
export function entryDetail(row,data={},key=''){
 let calc='';if(['spells','activeAbilities','passiveAbilities','racialAbilities','feats'].includes(key))calc=calculationDetails(row,data,key);
 const labels={damage:'Damage',dmg:'Damage',range:'Range',duration:'Duration',target:'Target',saving_throw:'Save',school:'School',spell_resist:'Spell resistance',attack_type:'Attack',type:'Type',uses:'Uses',crit_range:'Critical range',crit_mult:'Critical multiplier',acBonus:'Armor bonus',checkPenalty:'Check penalty',cost:'Cost',slot:'Slots',at_higher_lvls:'At higher levels'};
 const dice=String(row.damage||row.dmg||'');const rollable=/^\s*\d{1,2}d\d{1,4}(?:\s*[+-]\s*\d{1,6})?\s*$/i.test(dice);
 return calc+(rollable&&!calc?'<button class="button" type="button" data-damage-roll="'+e(dice)+'" data-damage-label="'+e(row.name||'Damage')+'">Roll '+e(dice)+'</button>':'')+'<p class="cs-prose">'+e(row.desc||'No description.')+'</p><dl class="cs-pairs">'+Object.entries(labels).filter(([k])=>row[k]!==undefined&&row[k]!=='').map(([k,label])=>'<div><dt>'+label+'</dt><dd>'+e(row[k])+'</dd></div>').join('')+'</dl>'+(Array.isArray(row.attrs)?'<dl class="cs-pairs">'+row.attrs.map(a=>'<div><dt>'+e(a.name)+'</dt><dd>'+e(a.val)+'</dd></div>').join('')+'</dl>':'');
}
export function renderSkillRows(d,query=''){
 return '<div class="cs-skills">'+sheetSkills(d).map((row,index)=>({row,index})).filter(({row})=>(row.name+' '+(row.subName||'')).toLowerCase().includes(query.toLowerCase())).map(({row,index})=>`<div class="cs-skill"><button type="button" class="cs-skill-roll" data-roll="${e(row.name)}" data-bonus="${skillTotal(row,d)}"><span>${e(row.name)}${row.subName?' ('+e(row.subName)+')':''}<small>${e(String(row.stat||'').toUpperCase())} · ${number(row.lvl??row.ranks)} ranks${row.cs?' · class':''}</small></span><strong>${signed(skillTotal(row,d))}</strong></button><button type="button" class="cs-icon" data-edit-entry="skills:${index}" aria-label="Edit ${e(row.name)}">✎</button></div>`).join('')+'</div>';
}

function calculationDetails(row,data,key){
 try{
  const c=entryCalculations(row,data,key),spell=key==='spells';let damage='',damageError='';
  if(row.damage||row.dmg){try{damage=damageExpression(String(row.damage||row.dmg),c.ctx);diceTerms(damage);}catch(err){damageError=err.message;damage='';}}
  const details=[...(c.dc===null?(spell?[['Save DC','Set '+c.stat.toUpperCase()+' score and a valid spell level']]:[]):[['Save DC',c.dc],['DC formula',spell?'10 + spell level '+c.level+' + '+c.stat.toUpperCase()+' modifier '+c.ctx[c.stat.toUpperCase()]+' + adjustment '+number(row.dc_misc):row.dc_formula]]),...(spell?[['MP cost',c.mp===null?'Set spell level':c.mp],['Caster level',c.ctx.CL??'Set caster level for this spell'],['Casting ability',c.stat.toUpperCase()]]:[]),...(c.attack?[['Attack',c.attack.mode.replaceAll('_',' ')+' '+signed(c.attack.bonus)]]:[]),...(damage?[['Damage formula',damage]]:[]),...(c.range?[['Range',c.range]]:[]),...(key==='activeAbilities'&&c.maxUses>0?[['Uses',c.currentUses+' / '+c.maxUses],['Maximum uses formula',row.uses_formula||row.u_max]]:[])];
  return '<section class="cs-entry-calcs"><dl class="cs-pairs">'+details.map(([label,v])=>'<div><dt>'+e(label)+'</dt><dd>'+e(v)+'</dd></div>').join('')+'</dl><div class="cs-calculated-actions">'+(spell?'<button class="button" type="button" data-cast-entry="spells:'+(data.spells||[]).indexOf(row)+'" '+(c.mp===null?'disabled':'')+'>Cast'+(c.mp===null?'':' · '+c.mp+' MP')+'</button>':'')+(c.attack?'<button class="button" type="button" data-roll="'+e(row.name)+' attack" data-bonus="'+c.attack.bonus+'">Attack '+signed(c.attack.bonus)+'</button>':'')+(damage?'<button class="button" type="button" data-damage-roll="'+e(damage)+'" data-damage-label="'+e(row.name)+'">Roll '+e(damage)+'</button>':'')+(spell&&c.concentration!==null?'<button class="button" type="button" data-roll="'+e(row.name)+' concentration" data-bonus="'+c.concentration+'">Concentration '+signed(c.concentration)+'</button><button class="button" type="button" data-roll="'+e(row.name)+' caster level" data-bonus="'+c.ctx.CL+'">Caster level '+signed(c.ctx.CL)+'</button>':'')+'</div>'+(damageError?'<p class="cs-caption">'+e(damageError)+'</p>':'')+'</section>';
 }catch(err){return '<p class="cs-caption">'+e(err.message)+'</p>';}
}
